package web

import "html/template"

func init() {
	template.Must(pages.Parse(`{{define "connections"}}
<div class="page-head"><div><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Projects</a><span>/</span><a href="/connections">Repository connections</a></nav>
{{if eq .View "connections"}}<h1>Connect a repository</h1><p class="lede">Authorize in your browser or use an SSH access key. Local deployments use polling.</p>{{end}}
{{if eq .View "selection"}}<h1>Choose repository and branch</h1>{{end}}
{{if eq .View "ssh"}}<h1>Connect using SSH</h1>{{end}}
</div></div>
{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}
{{if eq .View "connections"}}<div class="grid providers">
{{range .Connections}}<section id="{{.Provider}}" class="provider"><div class="provider-head"><span class="provider-icon">{{template "i-branch"}}</span><h2>{{if eq .Provider "github"}}GitHub{{else}}Bitbucket Cloud{{end}}</h2>{{if .Connected}}<span class="status ok">Connected</span>{{else}}<span class="status idle">Not connected</span>{{end}}</div>
{{if .Connected}}<p><a class="button" href="/connections/{{.Provider}}/repositories">Choose repository and branch</a></p>{{end}}
{{if eq .Provider "github"}}<form method="post" action="/connections/github/start"><input type="hidden" name="_csrf" value="{{$.CSRF}}">{{if not .Configured}}<p class="muted">First connection: GitHub asks you to create this installation's App, then choose its repositories. Credentials are saved automatically.</p><label>Organization (optional)<input name="organization" placeholder="Leave empty for your personal repositories"></label>{{end}}<button{{if .Connected}} class="secondary"{{end}}>{{if .Connected}}Change authorized repositories{{else}}Connect GitHub{{end}}</button></form>
{{else}}{{if not .Configured}}<p class="muted">Bitbucket requires a one-time OAuth consumer setup in your workspace settings. After that, connect in your browser.</p><p><a href="https://support.atlassian.com/bitbucket-cloud/docs/use-oauth-on-bitbucket-cloud/" target="_blank" rel="noopener noreferrer">Open Bitbucket setup instructions ↗</a></p><p>Callback URL: <code>{{$.Origin}}/connections/bitbucket/callback</code></p><p class="muted">Permissions: Account → Read and Repositories → Read. Enable private consumer; leave write permissions disabled.</p>{{end}}<details {{if not .Configured}}open{{end}}><summary>OAuth consumer settings</summary><form method="post" action="/connections/bitbucket/settings"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><label>Consumer key<input name="client_id" required autocomplete="off"></label><label>Consumer secret<input type="password" name="client_secret" autocomplete="new-password" {{if not .Configured}}required{{end}}></label><button class="secondary">Save consumer settings</button></form></details><form method="post" action="/connections/bitbucket/start"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button{{if .Connected}} class="secondary"{{end}}>Connect Bitbucket</button></form>{{end}}
{{if .Connected}}<form method="post" action="/connections/{{.Provider}}/disconnect" class="provider-foot"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button class="ghost small">Disconnect locally</button><small class="muted">Provider access can be revoked in your provider's app settings.</small></form>{{end}}
</section>{{end}}
<section id="ssh" class="provider"><div class="provider-head"><span class="provider-icon">{{template "i-key"}}</span><h2>SSH access</h2></div><p class="muted">Generate a key here, copy the public key to repository settings, then test access. The private key stays on this host.</p><p><a class="button secondary" href="/connections/ssh">Connect using SSH</a></p></section></div>
{{if .SSHKeys}}<section><h2>Generated SSH keys</h2><p class="muted">Keys that no project uses are deleted automatically 24 hours after creation.</p><div class="scroll"><table><thead><tr><th>Repository</th><th>Created</th><th>Used by</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>{{range .SSHKeys}}<tr><td><a href="/connections/ssh/keys/{{.Key.ID}}">{{.Key.Repo}}</a></td><td>{{when .Key.Created}}</td><td>{{if .Users}}{{range $i, $u := .Users}}{{if $i}}, {{end}}{{$u}}{{end}}{{else}}<span class="muted">Unused</span>{{end}}</td><td class="row-action">{{if not .Users}}<form method="post" action="/connections/ssh/keys/{{.Key.ID}}/delete"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button class="secondary small" data-confirm="Delete this SSH key? Remove it from the repository's access keys too.">Delete</button></form>{{end}}</td></tr>{{end}}</tbody></table></div></section>{{end}}{{end}}
{{if eq .View "manifest"}}<section class="narrow-section"><h1>Continue on GitHub</h1><p>Register this instance's App and choose the repositories it can read.</p><form id="github-manifest" action="{{.ManifestAction}}" method="post" data-autosubmit><input type="hidden" name="manifest" value="{{.Manifest}}"><button>Continue on GitHub</button></form></section>{{end}}
{{if eq .View "connected"}}<section class="narrow-section"><h1>{{if .Error}}Connection needs attention{{else}}Repository provider connected{{end}}</h1>{{if not .Error}}<p><a class="button" href="/connections/{{.Provider}}/repositories">Choose repository and branch</a></p>{{end}}<p><a href="/connections">← Back to connections</a></p></section>{{end}}
{{if eq .View "selection"}}{{if eq .Provider "bitbucket"}}<form method="get" class="inline-form"><label>Workspace<select name="workspace">{{range .Workspaces}}<option value="{{.Slug}}" {{if eq $.Workspace .Slug}}selected{{end}}>{{.Name}}</option>{{end}}</select></label><button class="secondary">Show repositories</button></form>{{end}}
<section><h2>Repository</h2><ul class="repo-list">{{range .Repositories}}<li><a href="/connections/{{$.Provider}}/repositories?workspace={{$.Workspace}}&amp;repository={{.ID}}">{{template "i-branch"}}{{.FullName}}</a></li>{{else}}<li class="muted">No repositories found. Check authorized repositories and access permissions.</li>{{end}}</ul></section>{{if .Branches}}<section><h2>Branch and deployment</h2>{{template "projectForm" .}}</section>{{end}}{{end}}
{{if eq .View "ssh"}}{{if not .SSH.ID}}<section class="narrow-section"><form method="post" action="/connections/ssh/key"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label>GitHub or Bitbucket repository URL<input name="repo" placeholder="git@github.com:owner/repository.git" required></label><button>{{template "i-key"}}Generate access key</button></form></section>{{else}}<ol class="steps"><li class="step"><section><h2>Register the public key</h2><p class="repo">{{.SSH.Repo}}</p><textarea id="ssh-public-key" readonly rows="3">{{.SSH.PublicKey}}</textarea><div class="actions"><button type="button" class="secondary" data-copy="ssh-public-key">Copy public key</button><a class="button secondary" href="{{.AccessKeyURL}}" target="_blank" rel="noopener noreferrer">Open repository key settings ↗</a></div><p class="hint">Add the key with read-only access.</p></section></li>
<li class="step"><section><h2>Test access</h2><form method="post" action="/connections/ssh/keys/{{.SSH.ID}}/test"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button>Check connection and list branches</button></form><p class="hint">Host identity is verified against the provider's official HTTPS key source.</p></section></li>{{if .Branches}}
<li class="step"><section><h2>Choose branch and deploy</h2><p class="success">SSH access verified.</p>{{template "projectForm" .}}</section></li>{{end}}</ol>{{end}}{{end}}
{{end}}`))
}
